script:
api.addStyle('.customsuno-copy-song { display:inline-flex; align-items:center; margin:2px 6px; padding:3px 7px; border:1px solid #31858b; border-radius:5px; background:#153b3f; color:#a4f1f2; font:10px system-ui; cursor:pointer; vertical-align:middle; }');
api.observe('a[href*="/song/"]', link => {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'customsuno-copy-song';
  button.textContent = 'Link kopieren';
  button.title = 'CustomSuno: Song-Link kopieren';
  link.insertAdjacentElement('afterend', button);
  api.on(button, 'click', async event => {
    event.preventDefault(); event.stopPropagation();
    try { await navigator.clipboard.writeText(link.href); api.toast('Song-Link kopiert.'); }
    catch { api.toast('Zwischenablage nicht verfügbar.'); }
  });
  return () => button.remove();
});
